          '    # the page boots from. The mirror runs second because it reads what\n'
          '    # the pull wrote.\n'
          '    ("Constants export pull", ["tools/pull_constants_export.py"], ".",\n'
          '     ["data/constants_export.json", "data/constants_export.sha"]),\n'
