          '\n'
          "    # L-322, the gallery half. The suite proves the mirror's verdicts on\n"
          '    # fixtures, because no link in the real config can produce a\n'
          '    # relabel, a conflict or a definition until those rows are exported.\n'
          "    # The two checks below share the mirror's own reading, so one cause\n"
          '    # prints one explanation.\n'
          '    ("Mirror suite", "python",\n'
          '     ["test_mirror_constants.py"], "tools", None, False),\n'
          '\n'
          '    ("Config mirror check", "python",\n'
